#include <iostream>
#include <fstream>
#include <memory>

class FileOpener {
public:
  FileOpener(const std::string& filename) : file_(std::make_unique<std::ofstream>(filename)) {
    if (!file_->is_open()) {
      throw std::runtime_error("Could not open file!");
    }
  }
  ~FileOpener() {
    // Destructor automatically closes the file
    // even if exceptions are thrown
  }
  std::ofstream& getFile() { return *file_; }
private:
  std::unique_ptr<std::ofstream> file_;
};

int main() {
  try {
    FileOpener file("example.txt");
    file.getFile() << "Hello, RAII!\n";
  } catch (const std::runtime_error& error) {
    std::cerr << "Error: " << error.what() << std::endl;
  }
  return 0;
}
